    const dual=durMins(g(r,'flight_dualGiven'));
    const remarks=g(r,'flight_remarks');
    const schedOut=g(r,'flight_scheduledDepartureTime'),schedIn=g(r,'flight_scheduledArrivalTime'),schedBlock=diff(mins(schedOut),mins(schedIn));
    const f={dutyType,date,flightNo:g(r,'flight_flightNumber').toUpperCase(),dep:g(r,'flight_from').toUpperCase(),arr:g(r,'flight_to').toUpperCase(),reg:g(r,'aircraft_aircraftID').toUpperCase(),type:g(r,'aircraftType_type').toUpperCase(),schedOut,schedIn,schedBlock,onDuty:g(r,'flight_onDutyTime')||shiftTime(schedOut,-60),offDuty:g(r,'flight_offDutyTime')||shiftTime(schedIn,30),out,off,on,in:inn,block,flight:off&&on?diff(mins(off),mins(on)):0,credit:dutyType==='Flight'?credit(schedBlock):0,role:durMins(g(r,'flight_sic'))>0?'SIC':(g(r,'flight_selectedCrewInstructor')&& !durMins(g(r,'flight_pic'))?'Instructor':'PIC'),instructionType:(dutyType==='Flight'&&dual>0)?(remarks||'Training'):'',landings:Number(g(r,'flight_dayLandings')||0)+Number(g(r,'flight_nightLandings')||0),night:g(r,'flight_night')||'00:00',sim:isSimulator?'yes':'no',ifr:g(r,'flight_ifr')?'yes':'no',remarks,source:'logten'};
    let match=-1;
