    if(match>=0){fs[match]={...fs[match],...f,id:fs[match].id,_updatedAt:new Date().toISOString()};updated++}else{f.id=makeId();f._updatedAt=new Date().toISOString();fs.push(f);imported++}
    if(isSimulator)sims++;
