function applyCloudRows(rows){const byKind={};rows.forEach(r=>{const d=r.data||{};if(!d.kind||!d.payload)return;(byKind[d.kind]||(byKind[d.kind]=[])).push(d)});SYNC_KINDS.forEach(([key,kind])=>{const local=load(key),map=new Map(local.map(o=>[o.id,o]));for(const d of byKind[kind]||[]){const cur=map.get(d.itemId);if(!cur||String(d._updatedAt||'')>String(cur._updatedAt||''))map.set(d.itemId,d.payload)}save(key,[...map.values()])});SYNC_SINGLETONS.forEach(([key,kind])=>{const d=(byKind[kind]||[]).sort((a,b)=>String(b._updatedAt||'').localeCompare(String(a._updatedAt||'')))[0];if(!d)return;const cur=loadObject(key,{});if(!cur._updatedAt||String(d._updatedAt||'')>String(cur._updatedAt||''))localStorage.setItem(key,JSON.stringify(d.payload))})}
