function payrollData(month){const st=paySettings(),fs=load(FLIGHTS_KEY).filter(f=>inMonth(f.date,month)),trips=load(TRIPS_KEY).filter(t=>String(t.start||'').slice(0,7)===month),extras=monthExtras(month);const creditMins=sum(fs,f=>payrollCreditMins(f,st));const creditHours=creditMins/60;const training=fs.filter(trainingSector).length;const sims=fs.filter(isSim).length;const grounds=fs.filter(f=>f.dutyType==='Ground Course').length;const layMins=sum(trips,t=>t.layover);const layHours=layMins/60;const seniorPct=seniorityPct(st,month),seniority=Number(st.base||0)*seniorPct/100;const fixed=Number(st.base||0)+Number(st.allowance||0)+Number(st.transport||0)+seniority+Number(st.pos||0)+Number(st.telephone||0)+Number(st.uniform||0)+Number(st.meal||0)+Number(st.deduction||0);const flightPay=tierPay(creditHours,st),trainingPay=training*Number(st.trainingRate||0),layoverPay=layHours*Number(st.layoverRate||0),simPay=sims*Number(st.simAllowance||0),dayOffPay=Number(extras.dayOffCount||0)*Number(st.dayOffRate||0),arrears=Number(extras.arrears||0);const total=fixed+flightPay+trainingPay+layoverPay+simPay+dayOffPay+arrears;return{st,extras,creditMins,creditHours,training,sims,grounds,layMins,layHours,seniorPct,seniority,fixed,flightPay,trainingPay,layoverPay,simPay,dayOffPay,arrears,total}}
