async function fetchFxForDate(dateStr){for(let back=0;back<8;back++){const d=new Date(`${dateStr}T12:00:00Z`);d.setUTCDate(d.getUTCDate()-back);const key=dateKey(new Date(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()));try{const r=await fetch(`https://${key}.currency-api.pages.dev/v1/currencies/eur.json`,{cache:'no-store'});if(!r.ok)continue;const j=await r.json();const rate=Number(j&&j.eur&&j.eur.mad);if(rate>0)return{rate,date:j.date||key}}catch(e){}}throw new Error('FX unavailable')}
