function collectEntry(lockedOverride=null){const c=calcEntry(),dutyType=$('dutyTypeFlight').value,id=$('editId').value||makeId(),existing=load(FLIGHTS_KEY).find(x=>x.id===id);return{id,dutyType,date:$('date').value,flightNo:$('flightNo').value.trim().toUpperCase(),reg:$('reg').value.trim().toUpperCase(),type:$('type').value.trim().toUpperCase(),dep:$('dep').value.trim().toUpperCase(),arr:$('arr').value.trim().toUpperCase(),schedOut:$('schedOut').value,schedIn:$('schedIn').value,schedBlock:c.schedBlock,onDuty:$('onDuty').value,offDuty:$('offDuty').value,out:$('out').value,off:$('off').value,on:$('on').value,in:$('in').value,block:c.block,flight:c.flight,credit:c.credit,role:$('role').value,instructionType:$('instructionType').value,landings:Number($('landings').value||0),night:$('night').value,sim:dutyType==='Simulator'?'yes':'no',ifr:$('ifr').value,remarks:$('remarks').value.trim(),locked:lockedOverride===null?!!(existing&&existing.locked):!!lockedOverride,_updatedAt:new Date().toISOString()}}
function persistEntry(lockIt=false){const dutyType=$('dutyTypeFlight').value;if(!$('date').value){alert('Please enter the date.');return false}if((dutyType==='Flight'||dutyType==='DHD')&&(!$('dep').value.trim()||!$('arr').value.trim())){alert('Please enter From and To.');return false}const id=$('editId').value,fs=load(FLIGHTS_KEY),existing=id?fs.find(x=>x.id===id):null;if(existing&&existing.locked&&!lockIt){alert('This entry is locked. Unlock it before editing.');return false}const f=collectEntry(lockIt),i=fs.findIndex(x=>x.id===f.id);if(i>=0)fs[i]={...fs[i],...f};else fs.push(f);save(FLIGHTS_KEY,fs);return true}
$('flightForm').addEventListener('submit',e=>{e.preventDefault();const editing=!!$('editId').value;if(!persistEntry(false))return;resetEntry();render();show('dashboardView');alert(editing?'Entry updated.':'Entry saved.')});
$('clearForm').addEventListener('click',resetEntry);$('lockEntryBtn').addEventListener('click',()=>{const id=$('editId').value,fs=load(FLIGHTS_KEY),existing=id?fs.find(x=>x.id===id):null;if(existing&&existing.locked){if(!confirm('Unlock this entry and allow editing?'))return;existing.locked=false;existing._updatedAt=new Date().toISOString();save(FLIGHTS_KEY,fs);setEntryLockedUI(false);$('entryLockStatus').textContent='Unlocked. You can edit the entry again.';return}if(!confirm('Lock this entry? Its data will be protected from accidental editing.'))return;if(!persistEntry(true))return;render();setEntryLockedUI(true);$('entryLockStatus').textContent='LOCKED • Entry saved and protected.'});
$('dutyForm').addEventListener('submit',e=>{e.preventDefault();const ds=load(DUTY_KEY),rep=$('reportTime').value,end=$('endDuty').value;ds.push(stamp({id:makeId(),date:$('dutyDate').value,type:$('dutyType').value,report:rep,end,minutes:diff(mins(rep),mins(end)),notes:$('dutyNotes').value.trim()}));save(DUTY_KEY,ds);e.target.reset();$('dutyDate').value=today();render()});
$('tripStart').addEventListener('input',tripCalc);$('tripEnd').addEventListener('input',tripCalc);$('calcTrip').addEventListener('click',tripCalc);$('clearTrip').addEventListener('click',resetTrip);
$('tripForm').addEventListener('submit',e=>{e.preventDefault();const c=tripCalc();if(!c)return alert('Enter a valid Trip Start and Trip End.');const ts=load(TRIPS_KEY),id=$('tripEditId').value||makeId(),t={id,base:String(appSettings().homeBase||'CMN').toUpperCase(),stations:$('tripStations').value.trim().toUpperCase(),start:$('tripStart').value,end:$('tripEnd').value,trip:c.trip,duty:c.duty,layover:c.layover,block:c.block,remarks:$('tripRemarks').value.trim()};t._updatedAt=new Date().toISOString();const i=ts.findIndex(x=>x.id===id);if(i>=0)ts[i]=t;else ts.push(t);save(TRIPS_KEY,ts);resetTrip();renderTrips();alert('Trip saved.')});
$('exportCsv').addEventListener('click',()=>{const d=load(FLIGHTS_KEY);if(!d.length)return alert('No entries to export');const cols=['dutyType','date','flightNo','reg','type','dep','arr','schedOut','schedIn','schedBlock','onDuty','offDuty','out','off','on','in','block','credit','flight','role','instructionType','landings','night','ifr','remarks','locked'];download('pilotlog_logbook.csv',[cols.join(','),...d.map(r=>cols.map(c=>csv(r[c])).join(','))].join('\n'),'text/csv')});
$('exportLogTen').addEventListener('click',logTenExport);
$('logTenFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const r=logTenImport(await file.text());e.target.value='';render();renderTotals();renderPayroll();autoDetectTrips(false);$('logTenImportStatus').textContent=`Imported ${r.imported} new entries, updated ${r.updated}, simulators found ${r.sims}, duties ${r.duties}.`;
alert(`LogTen import complete\nNew entries: ${r.imported}\nUpdated existing: ${r.updated}\nSimulator rows: ${r.sims}\nDuties: ${r.duties}`)}catch(err){alert('LogTen import failed: '+err.message)}});

$('deleteAll').addEventListener('click',()=>{if(confirm('Delete all saved entries?')){localStorage.removeItem(FLIGHTS_KEY);render()}});$('clearRoster').addEventListener('click',()=>{if(confirm('Clear imported roster?')){localStorage.removeItem(ROSTER_KEY);render()}});
$('exportRoster').addEventListener('click',()=>{const d=load(ROSTER_KEY);if(!d.length)return alert('No roster to export');const cols=['date','flightNo','dep','arr','report','std','sta','endDuty','type','reg','status'];download('pilotlog_roster.csv',[cols.join(','),...d.map(r=>cols.map(c=>csv(r[c])).join(','))].join('\n'),'text/csv')});
$('calendarFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const events=parseIcs(await file.text());if(!events.length)throw new Error('No calendar events found.');const r=importCalendar(events);e.target.value='';autoDetectTrips(false);render();$('calendarImportStatus').textContent=`Imported ${r.sectors} flight sectors, ${r.duties} duties and ${r.other} other entries. ${r.skipped} duplicates/unsupported skipped.`;alert(`Imported: ${r.sectors} flights • ${r.duties} duties • ${r.other} other entries`)}catch(err){alert('Calendar import failed: '+err.message)}});
$('rosterFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const rows=parseCsv(await file.text());if(rows.length<2)return alert('CSV contains no data');const map=rows[0].map(fieldFor),imp=rows.slice(1).map(r=>{const o={id:makeId(),status:'planned'};map.forEach((k,i)=>{if(k)o[k]=r[i]||''});o.date=normalDate(o.date);['dep','arr','flightNo','type','reg'].forEach(k=>o[k]=(o[k]||'').toUpperCase());return o}).filter(x=>x.date&&(x.dep||x.arr||x.flightNo));save(ROSTER_KEY,[...load(ROSTER_KEY),...imp]);e.target.value='';render();alert(`${imp.length} roster sectors imported`)});

