$('resetPaySettings').addEventListener('click',()=>{if(confirm('Restore the rates from your Excel file?')){localStorage.setItem(PAY_SETTINGS_KEY,JSON.stringify(PAY_DEFAULTS));fillPaySettings();renderPayroll()}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-delete-flight]');if(b){save(FLIGHTS_KEY,load(FLIGHTS_KEY).filter(f=>f.id!==b.dataset.deleteFlight));render();return}b=e.target.closest('[data-edit-flight]');if(b){const f=load(FLIGHTS_KEY).find(x=>x.id===b.dataset.editFlight);if(!f)return;$('editId').value=f.id;['dutyTypeFlight','date','flightNo','reg','type','dep','arr','schedOut','schedIn','onDuty','offDuty','out','off','on','in','role','instructionType','landings','night','ifr','remarks'].forEach(id=>{const key={dutyTypeFlight:'dutyType'}[id]||id;if($(id))$(id).value=f[key]??''});$('entryTitle').textContent=f.locked?'View locked entry':'Edit log entry';$('saveEntryBtn').textContent='Update entry';$('onDuty').dataset.manual=f.onDuty?'1':'';$('offDuty').dataset.manual=f.offDuty?'1':'';calcEntry();setEntryLockedUI(!!f.locked);show('addView');return}b=e.target.closest('[data-delete-duty]');if(b){save(DUTY_KEY,load(DUTY_KEY).filter(d=>d.id!==b.dataset.deleteDuty));render();return}b=e.target.closest('[data-delete-trip]');if(b){save(TRIPS_KEY,load(TRIPS_KEY).filter(t=>t.id!==b.dataset.deleteTrip));renderTrips();return}b=e.target.closest('[data-roster-action]');if(b){const rs=load(ROSTER_KEY),r=rs.find(x=>x.id===b.dataset.rosterAction);if(!r)return;if(r.status==='done'){r.status='planned';save(ROSTER_KEY,rs);render();return}const existing=load(FLIGHTS_KEY).find(f=>f.date===r.date&&String(f.flightNo||'').toUpperCase()===String(r.flightNo||'').toUpperCase()&&f.dep===r.dep&&f.arr===r.arr);if(existing){const edit=document.querySelector(`[data-edit-flight="${existing.id}"]`);if(edit)edit.click();else{const f=existing;$('editId').value=f.id;$('date').value=f.date;$('flightNo').value=f.flightNo;$('dep').value=f.dep;$('arr').value=f.arr;$('schedOut').value=f.schedOut||r.std||'';$('schedIn').value=f.schedIn||r.sta||'';$('onDuty').value=f.onDuty||shiftTime($('schedOut').value,-60);$('offDuty').value=f.offDuty||shiftTime($('schedIn').value,30);calcEntry();show('addView')}}else{resetEntry();$('date').value=r.date||'';$('flightNo').value=r.flightNo||'';$('dep').value=r.dep||'';$('arr').value=r.arr||'';$('type').value=r.type||'';$('reg').value=r.reg||'';$('schedOut').value=r.std||'';$('schedIn').value=r.sta||'';applyDutyDefaults();calcEntry();$('remarks').value='Imported from roster'}r.status='done';save(ROSTER_KEY,rs);render();show('addView')}});
resetEntry();resetTrip();$('dutyDate').value=today();$('payrollMonth').value=monthNow();fillPaySettings();render();renderSettings();show('dashboardView');updateCloudStatus();console.log('PilotLog v'+VERSION+' loaded');
